void NetworkDetails::set_configured(
    ConfiguredNetworkDetailsPtr configured) {
  if (tag_ == Tag::kConfigured) {
    *(data_.configured) = std::move(configured);
  } else {
    DestroyActive();
    tag_ = Tag::kConfigured;
    data_.configured = new ConfiguredNetworkDetailsPtr(
        std::move(configured));
  }
}

void NetworkDetails::DestroyActive() {
  switch (tag_) {

    case Tag::kVisible:

      delete data_.visible;
      break;
    case Tag::kConfigured:

      delete data_.configured;
      break;
  }
}

