// static
bool UnionTraits<::arc::mojom::NetworkDetails::DataView, ::arc::mojom::NetworkDetailsPtr>::Read(
    ::arc::mojom::NetworkDetails::DataView input,
    ::arc::mojom::NetworkDetailsPtr* output) {
  using UnionType = ::arc::mojom::NetworkDetails;
  using Tag = UnionType::Tag;

  switch (input.tag()) {
    case Tag::kVisible: {
      ::arc::mojom::VisibleNetworkDetailsPtr result_visible;
      if (!input.ReadVisible(&result_visible))
        return false;

      *output = UnionType::NewVisible(
          std::move(result_visible));
      break;
    }
    case Tag::kConfigured: {
      ::arc::mojom::ConfiguredNetworkDetailsPtr result_configured;
      if (!input.ReadConfigured(&result_configured))
        return false;

      *output = UnionType::NewConfigured(
          std::move(result_configured));
      break;
    }
    default:

      return false;
  }
  return true;
}

// static
bool UnionTraits<::arc::mojom::ArcProxyInfo::DataView, ::arc::mojom::ArcProxyInfoPtr>::Read(
    ::arc::mojom::ArcProxyInfo::DataView input,
    ::arc::mojom::ArcProxyInfoPtr* output) {
  using UnionType = ::arc::mojom::ArcProxyInfo;
  using Tag = UnionType::Tag;

  switch (input.tag()) {
    case Tag::kManualProxy: {
      ::arc::mojom::ManualProxyConfigPtr result_manual_proxy;
      if (!input.ReadManualProxy(&result_manual_proxy))
        return false;

      *output = UnionType::NewManualProxy(
          std::move(result_manual_proxy));
      break;
    }
    case Tag::kPacUrlProxy: {
      ::arc::mojom::PacUrlProxyConfigPtr result_pac_url_proxy;
      if (!input.ReadPacUrlProxy(&result_pac_url_proxy))
        return false;

      *output = UnionType::NewPacUrlProxy(
          std::move(result_pac_url_proxy));
      break;
    }
    default:

      return false;
  }
  return true;
}

